// Same test as lib-thehive-writeback: first line exactly the marker line,
// author n8n's account.
const input = $('Called by a workflow').first().json;
const wb = input.config.writeback;
const firstLine = `${wb.marker} wazuh-alert-id=${input.wazuh_alert_id}`;
const comments = $('Answered: List TheHive comments?').first().json;
const obs = $input.first().json;
const bad = [comments, obs].find((r) => r.statusCode !== 200 || !Array.isArray(r.body));
if (bad) {
  return [{ json: { ok: false, stage: bad === comments ? 'List TheHive comments' : 'List TheHive observables',
    message: `HTTP ${bad.statusCode}: ${JSON.stringify(bad.body)}`.slice(0, 500) } }];
}
const writeback = comments.body.find((cm) => (cm.createdBy ?? cm._createdBy) === wb.author
  && typeof cm.message === 'string' && cm.message.split('\n')[0] === firstLine);
return [{ json: { ok: true, writeback_exists: Boolean(writeback), writeback_comment_id: writeback?._id ?? null,
  observables: obs.body.map((o) => ({ id: o._id, dataType: o.dataType, data: o.data, tags: o.tags ?? [] })) } }];
